package com.deliverysaas.audit;
import java.time.Instant;import java.util.UUID;import org.springframework.data.domain.*;import org.springframework.format.annotation.DateTimeFormat;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import com.deliverysaas.shared.error.ForbiddenException;import com.deliverysaas.shared.security.AuthPrincipal;import com.deliverysaas.users.domain.UserRole;
import org.springframework.data.web.PageableDefault;
@RestController @RequestMapping("/api/v1/audit-logs") public class AuditLogController{private final AuditService service;public AuditLogController(AuditService s){service=s;}@GetMapping public Page<AuditLogResponse> search(@AuthenticationPrincipal AuthPrincipal p,@RequestParam(required=false)UUID userId,@RequestParam(required=false)String action,@RequestParam(required=false)String entityType,@RequestParam(required=false)UUID entityId,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME)Instant from,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME)Instant to,@PageableDefault(size=25,sort="createdAt",direction=Sort.Direction.DESC)Pageable pageable){if(p.role()!=UserRole.ADMIN)throw new ForbiddenException("Admin role required");return service.search(p.organizationId(),userId,action,entityType,entityId,from,to,pageable);}}
